INSERT INTO _migration_433_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_cells_s1_001', 'topic_alevel_bio_cells', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which level of protein structure refers to the sequence of amino acids in a polypeptide chain?', 'multiple_choice', NULL, '["A. Primary structure","B. Secondary structure","C. Tertiary structure","D. Quaternary structure"]', 'A', 'The primary structure is the linear sequence of amino acids joined by peptide bonds. Secondary structure is local folding into alpha-helices and beta-pleated sheets held by hydrogen bonds, tertiary structure is the overall three-dimensional fold of one chain, and quaternary structure requires more than one polypeptide subunit. Therefore the correct answer is A: Primary structure.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_cells_s1_002', 'topic_alevel_bio_cells', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which organelle is the site of protein synthesis (translation) in a eukaryotic cell?', 'multiple_choice', NULL, '["A. Lysosome","B. Ribosome","C. Golgi apparatus","D. Smooth endoplasmic reticulum"]', 'B', 'Ribosomes bind messenger RNA and assemble amino acids into polypeptides during translation. Lysosomes contain hydrolytic enzymes for digestion, the Golgi apparatus modifies and packages proteins, and the smooth endoplasmic reticulum synthesises lipids rather than proteins. Therefore the correct answer is B: Ribosome.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_cells_s1_003', 'topic_alevel_bio_cells', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A plant cell is placed in pure water. Which statement describes what happens?', 'multiple_choice', NULL, '["A. Water leaves by osmosis and the cell becomes flaccid","B. Water enters by active transport and the cell bursts","C. Water enters by osmosis and the cell becomes turgid but does not burst","D. There is no net movement of water in either direction"]', 'C', 'Pure water has a higher (less negative) water potential than the cell sap, so water moves into the cell by osmosis across the partially permeable membrane. The inelastic cellulose cell wall resists expansion and builds up pressure potential, so the cell becomes turgid rather than bursting. Therefore the correct answer is C: Water enters by osmosis and the cell becomes turgid but does not burst.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_cells_s1_004', 'topic_alevel_bio_cells', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which reagent and result confirm the presence of a reducing sugar in a food sample?', 'multiple_choice', NULL, '["A. Biuret reagent, giving a purple colour","B. Iodine solution, giving a blue-black colour","C. Ethanol followed by water, giving a milky emulsion","D. Benedict''s reagent, heated, giving a brick-red precipitate"]', 'D', 'Reducing sugars reduce the blue copper(II) sulfate in Benedict''s reagent to brick-red copper(I) oxide when heated. Biuret reagent detects peptide bonds in protein, iodine detects starch, and the ethanol emulsion test detects lipids. Therefore the correct answer is D: Benedict''s reagent, heated, giving a brick-red precipitate.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_cells_s1_005', 'topic_alevel_bio_cells', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In a sample of double-stranded DNA, 22% of the bases are adenine. What percentage of the bases are cytosine?', 'multiple_choice', NULL, '["A. 28%","B. 22%","C. 44%","D. 56%"]', 'A', 'By Chargaff''s base-pairing rules A = T, so thymine is also 22% and A + T together make 44%. The remaining 56% is shared equally between guanine and cytosine because G = C, so cytosine is 28%. Therefore the correct answer is A: 28%.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_cells_s1_006', 'topic_alevel_bio_cells', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A student investigates the biochemical composition of food samples and how amino acids are joined together.', 'structured', NULL, NULL, '(a) Shake the sample with ethanol to dissolve any lipid, then pour the ethanol into water. A cloudy (milky-white) emulsion is a positive result, because the lipid comes out of solution as tiny droplets when diluted. (b) Boil the sample with dilute hydrochloric acid to hydrolyse the disaccharide, neutralise it, then heat with Benedict''s reagent; a brick-red (orange-red) precipitate is the positive result. (c) The carboxyl group of one amino acid reacts with the amino group of the other and a molecule of water is released as the peptide bond forms; reactions that join two molecules with the loss of water are called condensation reactions.', '(a) Shake the sample with ethanol to dissolve any lipid, then pour the ethanol into water. A cloudy (milky-white) emulsion is a positive result, because the lipid comes out of solution as tiny droplets when diluted. (b) Boil the sample with dilute hydrochloric acid to hydrolyse the disaccharide, neutralise it, then heat with Benedict''s reagent; a brick-red (orange-red) precipitate is the positive result. (c) The carboxyl group of one amino acid reacts with the amino group of the other and a molecule of water is released as the peptide bond forms; reactions that join two molecules with the loss of water are called condensation reactions.', 'medium', '6', '6', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_433_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_albio_cells_s1_006_a', 'q_albio_cells_s1_006', 'a', 'Describe how the student would test a sample for the presence of lipid, including the expected positive result.', '2', 'Shake the sample with ethanol to dissolve any lipid, then pour the ethanol into water. A cloudy (milky-white) emulsion is a positive result, because the lipid comes out of solution as tiny droplets when diluted.', '1'),
('sqp_q_albio_cells_s1_006_b', 'q_albio_cells_s1_006', 'b', 'State the procedure and positive result for testing a sample for a non-reducing sugar.', '2', 'Boil the sample with dilute hydrochloric acid to hydrolyse the disaccharide, neutralise it, then heat with Benedict''s reagent; a brick-red (orange-red) precipitate is the positive result.', '2'),
('sqp_q_albio_cells_s1_006_c', 'q_albio_cells_s1_006', 'c', 'Explain why the formation of a peptide bond between two amino acids is described as a condensation reaction.', '2', 'The carboxyl group of one amino acid reacts with the amino group of the other and a molecule of water is released as the peptide bond forms; reactions that join two molecules with the loss of water are called condensation reactions.', '3');
INSERT INTO _migration_433_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_433_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_433_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'alevel-bio-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_433_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_433_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_433_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'alevel-bio-sprint1-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/', 0, 1 FROM _migration_433_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_433_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_433_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_433_expected e ON e.id = r.question_id WHERE r.batch_id IS 'alevel-bio-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_433_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_433_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
